#!/bin/bash

if [ $# -ne 1 ]; then
    echo "Error: This script requires exactly 1 arguments: dir. 'Data' of the DOTmark dataset" >&2
    echo "Usage: $0 <arg1>" >&2
    exit 1
fi

IDIR=$(readlink -e ${1})

# test that data dir is a subdir
if [[ $(realpath --relative-base="$PWD" "$IDIR") == /* ]]; then
    echo "Error: $IDIR is not a subdirectory of $PWD"
    exit 1
fi

# Continue with your script here
echo "Safe to proceed"

# create destination dir
DDIR=$(mktemp -d -p $(pwd) allinstances.XXXXXXXX)
echo "All instances in directory: $DDIR"

